import React, { useEffect, useState } from "react";
import "./Profile.css";

const Profile = () => {
  const [project, setProject] = useState(null);

  // Mock fetching data from database
  useEffect(() => {
    const mockData = {
      type: "Project",
      projectId: 1489,
      companyId: 36,
      title: "Software Developer",
      description: "Job Description: Are you a talented Software Developer with a passion for creating innovative web-based platforms? Join our dynamic team and play a key role in developing our groundbreaking new product.",
      projectType: "Short-term",
      paymentType: "Hourly",
      workMode: "Hybrid",
      requiredExperience: "Beginner",
      requiredSkills: ["JavaScript", "AngularJS", "Python", "HTML5", "CSS"],
      teamSize: 6,
      duration: "1 year",
      domain: "Web Development",
      salary: "$50/hr",
      createdAt: "2025-10-19T22:44:13.379214"
    };

    // Simulate async fetch
    setTimeout(() => setProject(mockData), 500);
  }, []);

  if (!project) return <p style={{ padding: "20px" }}>Loading project details...</p>;

  return (
    <div className="profile-container">
      <h1 className="profile-title">{project.title}</h1>
      <div className="profile-card">
        <p><b>Type:</b> {project.type}</p>
        <p><b>Project ID:</b> {project.projectId}</p>
        <p><b>Company ID:</b> {project.companyId}</p>
        <p><b>Description:</b> {project.description}</p>
        <p><b>Project Type:</b> {project.projectType}</p>
        <p><b>Payment Type:</b> {project.paymentType}</p>
        <p><b>Work Mode:</b> {project.workMode}</p>
        <p><b>Required Experience:</b> {project.requiredExperience}</p>
        <p><b>Required Skills:</b> {project.requiredSkills.join(", ")}</p>
        <p><b>Team Size:</b> {project.teamSize}</p>
        <p><b>Duration:</b> {project.duration}</p>
        <p><b>Domain:</b> {project.domain}</p>
        <p><b>Salary:</b> {project.salary}</p>
        <p><b>Created At:</b> {new Date(project.createdAt).toLocaleString()}</p>
      </div>
    </div>
  );
};

export default Profile;
